-- VULNERABLE: user input concatenated directly into the statement
DECLARE @userInput VARCHAR(100) = '5 OR 1=1; DROP TABLE Employees;--';
DECLARE @badSql NVARCHAR(MAX) =
    N'SELECT * FROM Employees WHERE employee_id = ' + @userInput;
EXEC(@badSql);  -- input is interpreted as SQL: injection!

-- SAFE: value passed as a typed bind parameter
DECLARE @id INT = 5;
DECLARE @goodSql NVARCHAR(MAX) =
    N'SELECT * FROM Employees WHERE employee_id = @empId';
EXEC sp_executesql
    @goodSql,
    N'@empId INT',   -- parameter definition
    @empId = @id;    -- bound value, never parsed as code

CREATE OR REPLACE FUNCTION search_employees(
    p_dept   TEXT DEFAULT NULL,
    p_minsal NUMERIC DEFAULT NULL
) RETURNS SETOF employees AS $$
DECLARE
    v_sql  TEXT := 'SELECT * FROM employees WHERE 1=1';
BEGIN
    IF p_dept IS NOT NULL THEN
        v_sql := v_sql || ' AND department = $1';
    END IF;
    IF p_minsal IS NOT NULL THEN
        v_sql := v_sql || ' AND salary >= $2';
    END IF;

    RETURN QUERY EXECUTE v_sql USING p_dept, p_minsal;
END;
$$ LANGUAGE plpgsql;

DECLARE @cols NVARCHAR(MAX), @sql NVARCHAR(MAX);

-- Build a safely quoted, comma-separated column list from data
SELECT @cols = STRING_AGG(QUOTENAME(category), ',')
FROM (SELECT DISTINCT category FROM sales) AS c;

SET @sql = N'
SELECT region, ' + @cols + N'
FROM (SELECT region, category, amount FROM sales) src
PIVOT (SUM(amount) FOR category IN (' + @cols + N')) pvt;';

EXEC sp_executesql @sql;
